// Build the GHL upsert body. First touch fields are only written when the contact does not have them yet.
const form = $('Form Webhook').first().json.body || {};
const existing = ($input.first().json && $input.first().json.contact) || null;
const existingFields = {};
if (existing && Array.isArray(existing.customFields)) {
  for (const f of existing.customFields) existingFields[f.id] = f.value;
}
const clean = v => (v === undefined || v === null) ? '' : String(v).trim().slice(0, 250);

// Map form values to GHL custom field keys. Create these fields in GHL first.
const lastTouch = {
  last_touch_source: form.lt_source,
  last_touch_medium: form.lt_medium,
  last_touch_campaign: form.lt_campaign,
  utm_content: form.utm_content,
  utm_term: form.utm_term,
  fbclid: form.fbclid,
  fbc: form.fbc,
  referrer: form.referrer,
  landing_page: form.landing_page
};
const firstTouch = {
  first_touch_source: form.ft_source,
  first_touch_medium: form.ft_medium,
  first_touch_campaign: form.ft_campaign,
  first_touch_date: form.ft_timestamp
};

const customFields = [];
for (const [key, val] of Object.entries(lastTouch)) {
  if (clean(val)) customFields.push({ key, field_value: clean(val) });
}
// Only send first touch for new contacts, so it is never overwritten.
if (!existing) {
  for (const [key, val] of Object.entries(firstTouch)) {
    if (clean(val)) customFields.push({ key, field_value: clean(val) });
  }
}

const source = [clean(form.lt_source) || 'direct', clean(form.lt_medium), clean(form.lt_campaign)].filter(Boolean).join(' / ');

return [{ json: {
  locationId: $env.GHL_LOCATION_ID,
  firstName: clean(form.first_name),
  email: clean(form.email),
  phone: clean(form.phone),
  source,
  tags: [clean(form.lt_medium) === 'boosted_post' ? 'src-boosted-post' : (clean(form.lt_medium) === 'paid_social' ? 'src-meta-ads' : 'src-other')],
  customFields,
  _isNewContact: !existing
} }];
